/**
 * Product Controller
 * Generated by BackendForge
 */
const { parsePagination, paginatedResponse } = require('../utils/pagination');
const { Product, Category, Review } = require('../models');
const { Op } = require('sequelize');

const productController = {
  async listProducts(req, res, next) {
    try {
      const pagination = parsePagination(req.query);
      const { search, category, minPrice, maxPrice, featured } = req.query;

      const where = { isActive: true };
      if (search) where.name = { [Op.iLike]: `%${search}%` };
      if (category) where.categoryId = category;
      if (minPrice) where.price = { ...where.price, [Op.gte]: parseFloat(minPrice) };
      if (maxPrice) where.price = { ...where.price, [Op.lte]: parseFloat(maxPrice) };
      if (featured === 'true') where.isFeatured = true;

      const { count: total, rows: products } = await Product.findAndCountAll({
        where,
        include: [{ model: Category, as: 'category', attributes: ['id', 'name', 'slug'] }],
        order: [[pagination.sort, pagination.order]],
        offset: pagination.offset, limit: pagination.limit,
      });

      res.json({ success: true, ...paginatedResponse(products, total, pagination) });
    } catch (error) { next(error); }
  },

  async getProduct(req, res, next) {
    try {
      const product = await Product.findByPk(req.params.id, {
        include: [
          { model: Category, as: 'category' },
          { model: Review, as: 'reviews', limit: 10, order: [['createdAt', 'DESC']] },
        ],
      });
      if (!product) return res.status(404).json({ success: false, message: 'Product not found' });
      res.json({ success: true, data: { product } });
    } catch (error) { next(error); }
  },

  async createProduct(req, res, next) {
    try {
      const product = await Product.create(req.body);
      res.status(201).json({ success: true, message: 'Product created', data: { product } });
    } catch (error) { next(error); }
  },

  async updateProduct(req, res, next) {
    try {
      const product = await Product.findByPk(req.params.id);
      if (!product) return res.status(404).json({ success: false, message: 'Product not found' });
      await product.update(req.body);
      if (!product) return res.status(404).json({ success: false, message: 'Product not found' });
      res.json({ success: true, message: 'Product updated', data: { product } });
    } catch (error) { next(error); }
  },

  async deleteProduct(req, res, next) {
    try {
      await Product.destroy({ where: { id: req.params.id } }); // Soft delete (paranoid)
      res.json({ success: true, message: 'Product deleted' });
    } catch (error) { next(error); }
  },
};

module.exports = productController;
